+    let p = dto.to_params();
+    assert!(matches!(p.style, ViseStyle::SelfCentering(sc) if !sc.has_grip()), "no step");
+    assert_eq!(serde_json::to_string(&ViseDto::from_params(&p)).expect("writes"), old, "and writes back byte for byte");
